/* GitHub Pages reads aggregate data generated by Python in GitHub Actions.
   No synthetic or illustrative counts are displayed as research findings. */
const $ = (id) => document.getElementById(id);
const labels = ['Top left','Top middle','Top right','Bottom left','Bottom middle','Bottom right'];
const monthNames = {4:'April',5:'May',6:'June',7:'July',8:'August'};
const number = new Intl.NumberFormat('en-CA');
let dataset = null;

function element(tag, className, text) {
  const e = document.createElement(tag);
  if (className) e.className = className;
  if (text !== undefined) e.textContent = String(text);
  return e;
}
function option(parent, value, label) {
  const op = element('option','',label);
  op.value = String(value);
  parent.appendChild(op);
}
function renderTrail(data) {
  const out = $('click-trail');
  out.replaceChildren();
  if (!data.maya_session || !data.maya_session.length) {
    $('session-state').textContent = 'Anonymous session 18817 was not found. No clicks were invented.';
    return;
  }
  $('session-state').textContent = 'Anonymous session 18817 · ' + data.maya_session.length + ' recorded product clicks';
  for (const click of data.maya_session) {
    const card = element('article','trail-item');
    card.appendChild(element('span','index','CLICK ' + click.order));
    card.appendChild(element('h3','',click.model || 'Product code unavailable'));
    card.appendChild(element('p','','Position: ' + (click.position || 'not recorded')));
    card.appendChild(element('p','','Category code: ' + click.category));
    card.appendChild(element('p','','Price: ' + (click.price === null ? 'not recorded' : '$' + click.price.toFixed(2))));
    out.appendChild(card);
  }
}
function renderChart() {
  if (!dataset) return;
  const month = $('month').value;
  const category = $('category').value;
  const rows = dataset.counts.filter((r) => (month === 'all' || String(r.month) === month)
    && (category === 'all' || String(r.category) === category));
  const counts = labels.map((_,i) => rows.filter(r => Number(r.location) === i+1)
    .reduce((sum,r) => sum + Number(r.clicks), 0));
  const total = counts.reduce((a,b)=>a+b,0);
  const shares = counts.map(n => total ? 100*n/total : 0);
  $('n-clicks').textContent = number.format(total);
  $('n-sessions').textContent = number.format(dataset.total_sessions);
  $('n-share').textContent = total ? Math.max(...shares).toFixed(1)+'%' : '—';
  $('chart-state').textContent = total ?
    'Share of recorded product clicks in the selected data. These percentages are not click-through rates.' :
    'No recorded clicks match these filters.';
  const grid = $('screen-grid');
  const bars = $('position-bars');
  grid.replaceChildren(); bars.replaceChildren();
  for (let i=0;i<6;i++) {
    const cell = element('div','screen-cell');
    cell.style.backgroundColor = 'rgba(119,113,181,'+(0.08 + shares[i]/100*0.62)+')';
    cell.appendChild(element('small','',labels[i]));
    cell.appendChild(element('strong','',shares[i].toFixed(1)+'%'));
    grid.appendChild(cell);
    const line = element('div','barline');
    line.appendChild(element('span','',labels[i]));
    const track = element('div','track');
    const fill = element('div','fill');
    fill.style.width = shares[i].toFixed(2)+'%';
    track.appendChild(fill); line.appendChild(track);
    line.appendChild(element('strong','',number.format(counts[i])));
    bars.appendChild(line);
  }
}
async function main() {
  try {
    const response = await fetch('./data/summary.json',{cache:'no-cache'});
    if (!response.ok) throw new Error('Summary data file is not published yet (HTTP '+response.status+').');
    dataset = await response.json();
    if (!dataset || !Array.isArray(dataset.counts)) throw new Error('Summary format is invalid.');
    for (const m of dataset.months) option($('month'),m,monthNames[m] || 'Month '+m);
    for (const c of dataset.categories) option($('category'),c,'Category '+c);
    $('month').addEventListener('change',renderChart);
    $('category').addEventListener('change',renderChart);
    renderTrail(dataset);
    renderChart();
  } catch (error) {
    const msg = 'Real-data visualization is unavailable: '+error.message
      +' The GitHub Actions build must complete successfully before the charts appear.';
    $('session-state').textContent = msg;
    $('chart-state').textContent = msg;
  }
}
main();
